import test from 'node:test';import assert from 'node:assert/strict';import {Site} from '../src/site.js';import {emptyProject} from '../src/codec.js';import {Resources} from '../src/resources.js';import {ChunkMesher} from '../src/chunk-mesh.js';import {chunkInView,modelViewMargin} from '../src/chunk-view.js';
const left=[[1,0,0,0],[-1,0,0,15]],right=[[1,0,0,-48],[-1,0,0,80]];
function scene(){const p=emptyProject();p.size=[80,4,4];p.palette=[{Name:'minecraft:oak_planks'}];p.blocks=[{pos:[2,1,2],state:0},{pos:[50,1,2],state:0}];return new Site(p);}
test('view-driven meshing evicts geometry and loads the new view without mutating data',()=>{const s=scene(),before=s.pack(),m=new ChunkMesher(),r=new Resources(),a=m.render(s,r,{viewPlanes:left});assert.equal(a.chunks.length,1);assert.equal(a.stats.resident,1);const b=m.render(s,r,{viewPlanes:right});assert.equal(b.reset,false);assert.ok(b.evicted.includes('0,0,0'));assert.ok(b.chunks.some(c=>c.key==='3,0,0'));assert.deepEqual(s.pack(),before);const all=m.render(s,r,{});assert.equal(all.stats.resident,2);});
test('off-view edits remain canonical and are rebuilt when their chunks become visible',()=>{const s=scene(),m=new ChunkMesher(),r=new Resources();m.render(s,r,{viewPlanes:left});s.operations([{type:'set',pos:[51,1,2],state:{Name:'minecraft:glass'}}],{});m.changed(s);assert.equal(m.render(s,r,{viewPlanes:left}).chunks.length,0);const result=m.render(s,r,{viewPlanes:right});assert.ok(result.chunks.some(c=>c.key==='3,0,0'));assert.equal(s.palette[s.at([51,1,2]).state].Name,'minecraft:glass');assert.equal(m.render(s,r,{viewPlanes:right}).chunks.length,0);});
test('chunk bounds use conservative plane intersection',()=>{assert.equal(chunkInView('0,0,0',left),true);assert.equal(chunkInView('3,0,0',left),false);assert.equal(chunkInView('1,0,0',[[-1,0,0,16]]),true);});

test('oversized resource models crossing a chunk edge are kept visible',()=>{const margin=modelViewMargin({parts:[{elements:[{from:[-800,0,0],to:[16,16,16],rotation:{origin:[8,8,8],axis:'y',angle:45,rescale:true}}]}]});assert.ok(margin>50);assert.equal(chunkInView('3,0,0',left,margin),true);assert.equal(chunkInView('3,0,0',left,Infinity),true);});
